function reconcileAgentLog(lines) {
  const produced = [];
  const retry = [];
  let verifiedTestCount = 0;

  for (const line of lines) {
    if (line.includes("task <id> settled produced")) {
      const id = line.split("task ")[1].split(" settled")[0];
      produced.push(id);
    } else if (line.includes("task <id> retry scheduled")) {
      const id = line.split("task ")[1].split(" retry")[0];
      retry.push(id);
    } else if (line.includes("test exit=0") && line.includes("tests:")) {
      const testsMatch = line.match(/tests:(\d+)/);
      if (testsMatch) {
        verifiedTestCount += parseInt(testsMatch[1], 10);
      }
    }
  }

  return {
    produced: [...new Set(produced)].sort(),
    retry: [...new Set(retry)].sort(),
    verifiedTestCount
  };
}
```

