function isPathWithin(root, target) {
  if (typeof root !== 'string' || typeof target !== 'string') return false;
  const rootLower = root.toLowerCase();
  const targetLower = target.toLowerCase();

  // Check for Windows drive-absolute paths
  if (!rootLower.startsWith('\\\\') && !rootLower.match(/^[a-z]:/)) return false;
  if (!targetLower.startsWith('\\\\') && !targetLower.match(/^[a-z]:/)) return false;

  // Different drives
  if (rootLower[0] !== targetLower[0]) return false;

  const rootParts = rootLower.split(/[\\\/]+/).filter(part => part !== '.' && part !== '');
  const targetParts = targetLower.split(/[\\\/]+/).filter(part => part !== '.' && part !== '');

  // Handle ".." traversal
  for (let i = 0; i < targetParts.length; i++) {
    if (targetParts[i] === '..') {
      if (rootParts.length <= 0) return false;
      rootParts.pop();
    } else {
      break;
    }
  }

  // Check if target is within root
  for (let i = 0; i < rootParts.length; i++) {
    if (i >= targetParts.length || rootParts[i] !== targetParts[i]) {
      return false;
    }
  }

  return true;
}
