function isPathWithin(root, target) {
  if (typeof root !== 'string' || typeof target !== 'string') return false;
  const rootLower = root.toLowerCase();
  const targetLower = target.toLowerCase();

  // Check for Windows drive-absolute paths
  if (!rootLower.startsWith('\\\\') && !rootLower.match(/^[a-z]:/)) {
    return false; // Not a Windows absolute path
  }

  // Normalize both paths (case-insensitive, slash direction, repeated separators, ".", "..")
  const normalizePath = (path) => {
    let parts = path.split(/[\\\/]+/).filter(p => p !== '' && p !== '.');
    for (let i = 0; i < parts.length; i++) {
      if (parts[i] === '..') {
        if (i === 0 || parts[i - 1] === '..') {
          return null; // Invalid path (traversal above root)
        }
        parts.splice(i - 1, 2);
        i -= 1;
      }
    }
    return parts.join('\\');
  };

  const normalizedRoot = normalizePath(rootLower);
  if (!normalizedRoot) return false;

  const normalizedTarget = normalizePath(targetLower);
  if (!normalizedTarget) return false;

  // Check if target is within root (case-insensitive)
  return normalizedTarget.startsWith(normalizedRoot + '\\') ||
         normalizedTarget === normalizedRoot;
}
