    const produced = [];
    const retry = [];
    let verifiedTestCount = 0;

    for (const line of lines) {
        if (/task (\d+) settled produced/.test(line)) {
            const id = RegExp.$1;
            if (!produced.includes(id)) {
                produced.push(id);
