        return [];
    }

    // Create a deep copy of rows to ensure immutability of the input array and its contents
    const copiedRows = JSON.parse(JSON.stringify(rows));

    // 1. Calculate ranks for all items
    const rankedItems = copiedRows.map((row, index) => {
        let rank = 0;
        if (typeof row.rank === 'number') {
            rank = row.rank;
        } else if (typeof row.rank === 'string' && !isNaN(parseFloat(row.rank))) {
             // Handle string representations of numbers if necessary, though the prompt implies numeric rank
             rank = parseFloat(row.rank);
        }

        return {
            originalRow: row,
            index: index, // Preserve original input order for tie-breaking
            rank: rank
        };
    });

    // 2. Sort based on criteria:
    // Primary sort key: ascending numeric rank (a.rank - b.rank)
    // Secondary sort key (tie-breaker): original index (a.index - b.index)
    rankedItems.sort((a, b) => {
        const rankA = a.rank === undefined || isNaN(a.rank) ? Infinity : a.rank;
        const rankB = b.rank === undefined || isNaN(b.rank) ? Infinity : b.rank;

        // Compare ranks (ascending order)
        if (rankA !== rankB) {
            return rankA - rankB;
