function reconcileAgentLog(lines) {
    const producedSet = new Set();
    const retrySet = new Set();
    let verifiedTestCount = 0;

    for (const line of lines) {
        if (line.includes("task ") && line.includes(" settled produced")) {
            const match = line.match(/task (\d+)/);
            if (match) {
                producedSet.add(match[1]);
            }
        } else if (line.includes("task ") && line.includes(" retry scheduled")) {
            const match = line.match(/task (\d+)/);
            if (match) {
                retrySet.add(match[1]);
            }
        } else if (line.includes("tests:") && line.includes(" exit=0")) {
            const testMatch = line.match(/tests:(\d+)/);
            if (testMatch) {
                verifiedTestCount += parseInt(testMatch[1], 10);
            }
        }
    }

    return {
        produced: Array.from(producedSet).sort((a, b) => parseInt(a, 10) - parseInt(b, 10)).join(','),
        retry: Array.from(retrySet).sort((a, b) => parseInt(a, 10) - parseInt(b, 10)).join(','),
        verifiedTestCount: verifiedTestCount
    };
}

