function isPathWithin(root, target) {
    // Helper to normalize a Windows absolute path
    function normalize(p) {
        if (typeof p !== 'string') return null;
        // Replace backslashes with forward slashes for uniformity
        var parts = p.split(/[\\/]+/);
        if (parts.length === 0) return null;
        // First part should be drive letter like "C:" or "c:"
        var drive = parts[0];
        if (!drive.match(/^[a-zA-Z]:$/)) return null;
        var comps = [];
        for (var i = 1; i < parts.length; i++) {
            var seg = parts[i];
            if (seg === '' || seg === '.') continue;
            if (seg === '..') {
                if (comps.length === 0) {
                    // Attempt to go above drive root
                    return null;
                }
                comps.pop();
            } else {
                comps.push(seg);
            }
        }
        return {drive: drive.toUpperCase(), comps: comps};
    }

    var normRoot = normalize(root);
    var normTarget = normalize(target);
    if (!normRoot || !normTarget) return false;
    if (normRoot.drive !== normTarget.drive) return false;

    var rlen = normRoot.comps.length;
    var tlen = normTarget.comps.length;
    if (rlen > tlen) return false; // root longer than target cannot be ancestor

    for (var i = 0; i < rlen; i++) {
        if (normRoot.comps[i].toLowerCase() !== normTarget.comps[i].toLowerCase()) {
            return false;
        }
    }
    return true;
}

