function sortByRank(rows) {
  const indexed = rows.map((row, i) => ({ row, index: i }));
  indexed.sort((a, b) => {
    if (a.row.rank < b.row.rank) return -1;
    if (a.row.rank > b.row.rank) return 1;
    return a.index - b.index;
  });
  return indexed.map(item => item.row);
}

