function canSettle(task, epoch) {
    if (task === null || typeof task !== 'object') return false;
    if (task.status !== 'running') return false;
    if (!Number.isInteger(task.fencingEpoch)) return false;
    if (!Number.isInteger(epoch)) return false;
    return task.fencingEpoch === epoch;
}

