function reconcileAgentLog(lines) {
  const producedSet = new Set();
  const retrySet = new Set();
  let verifiedTestCount = 0;
  for (const line of lines) {
    // task <id> settled produced
    const prodMatch = line.match(/task\s+(\S+)\s+settled\s+produced/);
    if (prodMatch) {
      producedSet.add(prodMatch[1]);
    }
    // task <id> retry scheduled
    const retryMatch = line.match(/task\s+(\S+)\s+retry\s+scheduled/);
    if (retryMatch) {
      retrySet.add(retryMatch[1]);
    }
    // tests:<integer> exit=0
    const testMatch = line.match(/tests:(\d+).*exit=0/);
    if (testMatch) {
      verifiedTestCount += parseInt(testMatch[1], 10);
    }
  }
  return {
    produced: Array.from(producedSet).sort(),
    retry: Array.from(retrySet).sort(),
    verifiedTestCount
  };
}

